mapper.update:
update MB_CCY_RATE
set
    RATE_TYPE = #{row.rateType,jdbcType=VARCHAR},            CCY = #{row.ccy,jdbcType=VARCHAR},            BRANCH = #{row.branch,jdbcType=VARCHAR},            COUNTRY = #{row.country,jdbcType=VARCHAR},            QUOTE_TYPE = #{row.quoteType,jdbcType=VARCHAR},            EXCH_BUY_RATE = #{row.exchBuyRate,jdbcType=DECIMAL},            EXCH_SELL_RATE = #{row.exchSellRate,jdbcType=DECIMAL},            MIDDLE_RATE = #{row.middleRate,jdbcType=DECIMAL},            NOTES_BUY_RATE = #{row.notesBuyRate,jdbcType=DECIMAL},            NOTES_SELL_RATE = #{row.notesSellRate,jdbcType=DECIMAL},            MAX_FLOAT_RATE_UP = #{row.maxFloatRateUp,jdbcType=DECIMAL},            MAX_FLOAT_RATE_DOWN = #{row.maxFloatRateDown,jdbcType=DECIMAL},            CENTRAL_BANK_RATE = #{row.centralBankRate,jdbcType=DECIMAL},            EFFECT_DATE = #{row.effectDate,jdbcType=TIMESTAMP},            EFFECT_TIME = #{row.effectTime,jdbcType=VARCHAR},            TRAN_TIMESTAMP = #{row.tranTimestamp,jdbcType=VARCHAR},            COMPANY = #{row.company,jdbcType=VARCHAR}

update MB_CCY_RATE
set
    COUNTRY = #{country,jdbcType=VARCHAR},            QUOTE_TYPE = #{quoteType,jdbcType=VARCHAR},            EXCH_BUY_RATE = #{exchBuyRate,jdbcType=DECIMAL},            EXCH_SELL_RATE = #{exchSellRate,jdbcType=DECIMAL},            MIDDLE_RATE = #{middleRate,jdbcType=DECIMAL},            NOTES_BUY_RATE = #{notesBuyRate,jdbcType=DECIMAL},            NOTES_SELL_RATE = #{notesSellRate,jdbcType=DECIMAL},            MAX_FLOAT_RATE_UP = #{maxFloatRateUp,jdbcType=DECIMAL},            MAX_FLOAT_RATE_DOWN = #{maxFloatRateDown,jdbcType=DECIMAL},            CENTRAL_BANK_RATE = #{centralBankRate,jdbcType=DECIMAL},            TRAN_TIMESTAMP = #{tranTimestamp,jdbcType=VARCHAR},            COMPANY = #{company,jdbcType=VARCHAR}        where RATE_TYPE = #{rateType,jdbcType=VARCHAR}
  and CCY = #{ccy,jdbcType=VARCHAR}
  and BRANCH = #{branch,jdbcType=VARCHAR}
  and EFFECT_DATE = #{effectDate,jdbcType=TIMESTAMP}
  and EFFECT_TIME = #{effectTime,jdbcType=VARCHAR}
